// One real sentence per word, for the Library's word page.
//
// The file behind this is generated by scripts/build-word-examples.ts from the
// grammar corpus and the vocabulary. It holds the CHOSEN sentence and nothing
// else, 2,989 rows and 576 KB against the 2.0 MB corpus it was picked out of,
// because the entry page needs one sentence and should not download 9,653 to
// find it. Why that shape, and how the choice is made, is in
// src/lib/library/word-example.ts.
//
// COVERAGE IS THE POINT OF THE `null` RETURN. 2,989 of 12,555 words (23.8%)
// have a sentence, but 430 of the first 500 words in teaching order (86.0%) do.
// So the section is present on nearly everything a beginner meets and absent
// across the long tail, and the page must render NOTHING when it is absent
// rather than a card explaining itself.
//
// ATTRIBUTION: Tatoeba, CC BY 2.0 FR. `id` is the Tatoeba sentence id and the
// permalink, kept so any sentence on screen traces back to the human who wrote
// it. The acknowledgment itself is the "About the data" link in the global
// sidebar (src/components/sidebar.tsx), reachable from every screen; /about/data
// names Tatoeba and the sentence data in full. See src/data/attribution.ts.
//
// PER-KANJI READINGS (SAK-95). `kr` is a second pass over this same file, run
// by scripts/ingest/sentence_readings.py AFTER build-word-examples.ts: one
// slot per KANJI CHARACTER in `jp`, left to right (kana characters contribute
// no slot). Each slot is either the same [kanji, surface-reading,
// base-reading] triple `VocabRow.align` already uses (src/data/vocab.ts), or
// null when that kanji's in-context reading could not be safely determined —
// a jukujikun the sentence tokenizer's dictionary reading doesn't survive
// aligner's rendaku rules, or a reading vocab.json never happened to attest.
// Null is a normal answer, not a gap to fill in later: see the script's
// module doc for the measured 95% per-kanji coverage and known caveats.

import examplesJson from "./generated/word-examples.json" with { type: "json" };

/** [kanji, surface-reading-in-this-sentence, base-reading], or null when this
 * kanji's reading could not be safely determined. Same shape as one slot of
 * `VocabRow.align`. */
export type KanjiReadingSlot = readonly [string, string, string] | null;

/** A word shown in a real sentence, with a human translation. */
export interface WordExample {
  /** The Tatoeba sentence id — the permalink, and the attribution. */
  readonly id: number;
  readonly jp: string;
  /** A HUMAN translation. Never machine-translated. */
  readonly en: string;
  /**
   * The `[start, end)` span within `jp` where this word occurs, to highlight.
   * The same convention SAK-40 uses for a grammar pattern's worked sentence
   * (see SentenceExampleView).
   *
   * THE SURFACE THIS SENTENCE WRITES, WHICH IS OFTEN NOT `keb` (SAK-97). The
   * span covers the word as it is inflected here: 2,172 of the 2,989 are the
   * dictionary spelling, and the other 817 are a form of it, so くすぐる is
   * underlined as くすぐらないで, ある as ありません, 包む as 包んで. This
   * comment said the opposite until SAK-422, and said it for long enough that
   * the source-pin test had to pin the difference as an exception set; the
   * data was right and the sentence is where a learner meets a conjugated
   * verb, so the comment was corrected and the exceptions are gone.
   *
   * Absent, not a guess, when no token in `jp` resolves to this word at all.
   * Pointing at the wrong characters is worse than pointing at nothing.
   *
   * It is scripts/ingest/sentence_readings.py that computes this, NOT
   * build-word-examples.ts, which always emits null: finding an inflected
   * surface needs a real tokenizer, so the span is filled in by the same
   * Python pass that fills in `kr`. See that script for the matching rule and
   * source-pins.test.ts for the check that every span is a surface of its own
   * word.
   */
  readonly span?: readonly [number, number];
  /** Per-kanji reading breakdown of `jp`. See the module header. */
  readonly kr: readonly KanjiReadingSlot[];
}

/** Tuple-packed on disk: [id, jp, en, start, end, kr]. start/end are null when
 * no token in the sentence resolved to this word, which leaves SAK-94 nothing
 * to highlight. A fixed six-element shape rather than a variable-length one
 * keeps this single format the only one two independent generation passes
 * (build-word-examples.ts for the sentence, sentence_readings.py for the span
 * and kr) both have to agree on. */
const RAW = examplesJson as unknown as Readonly<
  Record<
    string,
    readonly [number, string, string, number | null, number | null, readonly KanjiReadingSlot[]]
  >
>;

/** The example sentence for a word's written form, or null if it has none.
 * Absent is a normal answer for four words in five — see the header. */
export function exampleFor(keb: string): WordExample | null {
  const row = RAW[keb];
  if (!row) return null;
  const [id, jp, en, start, end, kr] = row;
  const span = start !== null && end !== null ? ([start, end] as const) : undefined;
  return span ? { id, jp, en, span, kr } : { id, jp, en, kr };
}

/** How many words have a sentence. Pinned by a test so a regenerated artifact
 * that silently loses most of its rows is caught. */
export const EXAMPLE_COUNT = Object.keys(RAW).length;
